# --- 인증 전 토큰을 찍어 본다 ---

public class LoudFilter extends UsernamePasswordAuthenticationFilter {
    @Override
    public Authentication attemptAuthentication(HttpServletRequest req,
            HttpServletResponse res) {
        Authentication before = UsernamePasswordAuthenticationToken
                .unauthenticated(req.getParameter("username"),
                                 req.getParameter("password"));
        System.out.println(">>> before principal   = " + before.getPrincipal());
        System.out.println(">>> before credentials = " + before.getCredentials());
        System.out.println(">>> before authorities = " + before.getAuthorities());
        System.out.println(">>> before authed      = " + before.isAuthenticated());

        Authentication after = super.attemptAuthentication(req, res);
        System.out.println(">>> after  principal   = " + after.getPrincipal());
        System.out.println(">>> after  credentials = " + after.getCredentials());
        System.out.println(">>> after  authorities = " + after.getAuthorities());
        System.out.println(">>> after  authed      = " + after.isAuthenticated());
        System.out.println(">>> after  details     = " + after.getDetails());
        System.out.println(">>> same class? "
                + (before.getClass() == after.getClass()));
        return after;
    }
}

