# --- setAuthenticated(true) 를 해 본다 ---

@GetMapping("/hack")
@ResponseBody
public String hack() {
    Authentication auth = SecurityContextHolder.getContext().getAuthentication();
    try {
        auth.setAuthenticated(true);
        return "ok";
    } catch (Exception e) {
        return e.getClass().getSimpleName() + ": " + e.getMessage();
    }
}

