@GetMapping("/hack2")
@ResponseBody
public String hack2() {
    Authentication forged = UsernamePasswordAuthenticationToken.authenticated(
            "admin", null,
            List.of(new SimpleGrantedAuthority("ROLE_ADMIN")));
    SecurityContextHolder.getContext().setAuthentication(forged);
    System.out.println(">>> " + forged.getName() + " "
            + forged.getAuthorities() + " " + forged.isAuthenticated());
    return "ok";
}

